using System;
using UnityEngine;

namespace TactileWars.Battle
{
    /// <summary>A linear map variant (same format as the handcrafted lane: spawn at the south end, two capture
    /// points, HQ at the north end, props). Applied at runtime by MapApplier over Battle.unity's handcrafted
    /// dressing, and by the base editor for the player's own base. Generated by the editor MapBuilder.
    /// Prop layouts, paths and sockets are our own designs (map content is not documented by any source).</summary>
    [CreateAssetMenu(menuName = "TactileWars/Map Layout Data")]
    public class MapLayoutData : ScriptableObject
    {
        public string id;
        public string displayName;
        public Vector3 playerSpawn = new Vector3(0f, 0f, 8f);
        public Vector3[] capturePoints = { new Vector3(0f, 0f, 43f), new Vector3(0f, 0f, 94f) };
        public Vector3 hq = new Vector3(0f, 0f, 105.5f);
        public Vector2 mapMin = new Vector2(-18f, 1f);
        public Vector2 mapMax = new Vector2(18f, 108f);
        public Vector2 focusMin = new Vector2(-1.5f, 9f);
        public Vector2 focusMax = new Vector2(1.5f, 99f);
        [Tooltip("Ground mask (R dirt path, G paving, B dark edge) over mapRect (x, z, width, depth).")] public Texture2D groundMask;
        public Vector4 mapRect = new Vector4(-40f, -25f, 80f, 160f);
        [Tooltip("Main path polyline (x, z), used by the editor overlay and the AI.")] public Vector2[] path = Array.Empty<Vector2>();
        public PropPlacement[] props = Array.Empty<PropPlacement>();
        [Tooltip("Spawn hatches: counterattack waves start at the one nearest the captured point.")] public Vector3[] spawnHatches = Array.Empty<Vector3>();

        [Header("Sockets for generated AI layouts (prop free)")]
        public Vector3[] squadSockets = Array.Empty<Vector3>();
        public Vector3[] mineSockets = Array.Empty<Vector3>();
        public Vector3[] defenseSockets = Array.Empty<Vector3>();

        [Header("Player base editing (estimates)")]
        [Tooltip("Defenses may not be placed south of this z (attacker start zone).")] public float attackerZoneMaxZ = 18f;
        [Tooltip("Placeable rectangle (x min, z min, x max, z max).")] public Vector4 placeable = new Vector4(-15.5f, 18f, 15.5f, 102f);
        [Tooltip("Keep this much clear around capture pads.")] public float padClearance = 3.6f;
    }

    [Serializable]
    public struct PropPlacement
    {
        public GameObject prefab;
        public Vector3 position;
        public float yaw;
        public float scale;
        [Tooltip("Blocking radius for placement and sockets (0 = decorative, does not block).")] public float radius;
    }
}
